import React, { useState } from 'react';
import './Skills.css';

function Skills() {
  const [selectedSkill, setSelectedSkill] = useState(null);

  const technicalSkills = [
    { name: 'Microsoft Office Suite', description: 'Daily use of Excel for data tracking and budgeting, PowerPoint for presentations, Word for documentation, and Outlook for stakeholder communication.' },
    { name: 'Google Workspace', description: 'Regular use of Docs, Sheets, Drive, and Gmail for collaboration, record-keeping, and team communication across projects.' },
    { name: 'Salesforce CRM', description: 'Used Salesforce to manage 200+ member account records, process transactions, and maintain data accuracy across an integrated database and event booking system.' },
    { name: 'Data Entry & Reporting', description: 'Accurate data entry and validation across integrated systems including CRM, POS, and membership databases; compiled reports to track program outcomes and participation.' },
    { name: 'AI Tools & Technologies', description: 'Applied AI tools in workshop facilitation and daily professional workflows, focused on practical problem-solving applications rather than theoretical use.' }
  ];

  const pmSkills = [
    { name: 'Stakeholder Management', description: 'Coordinated with university professors, external entrepreneurs, PMI chapter members, and community partners — aligning diverse stakeholders on planning, communication, and execution.' },
    { name: 'Cross-Functional Collaboration', description: 'Facilitated alignment across diverse teams and departments, coordinating group projects, balancing competing priorities, and maintaining clear communication throughout.' },
    { name: 'Budget Coordination', description: 'Estimated catering and venue costs for community workshop events; coordinated resource allocation and maintained budget documentation throughout the planning cycle.' },
    { name: 'Timeline Planning', description: 'Managed 2-month planning cycle for the AI Vibe Coding Workshop; tracked milestones and deliverables for GCU Women in Business mentorship program.' },
    { name: 'Team Leadership', description: 'Co-led cross-functional team to a 1st-place finish in the Harvard Business Simulation, coordinating strategic decisions across marketing, operations, finance, and sustainability.' },
    { name: 'Process Improvement', description: 'Identified and improved operational workflows; assisted in streamlining training and onboarding procedures to increase consistency and efficiency.' }
  ];

  const tools = [
    { name: 'Salesforce CRM', description: 'Managed high-volume member account data, processed daily transactions, and maintained accuracy across integrated CRM and event booking systems.' },
    { name: 'Microsoft Excel', description: 'Used for data tracking, budget estimation, reporting, and data validation across multiple projects and roles.' },
    { name: 'Google Sheets', description: 'Used for collaborative tracking, scheduling, and data documentation across team projects and event coordination.' },
    { name: 'Slack', description: 'Used for team communication and coordination across project planning and stakeholder engagement workflows.' },
    { name: 'Microsoft Teams', description: 'Used for virtual collaboration, scheduling, and cross-functional communication in academic and professional settings.' },
    { name: 'PowerPoint', description: 'Created presentations for stakeholder communication, event promotion, and academic project deliverables.' }
  ];

  const handleSkillClick = (skill) => {
    setSelectedSkill(selectedSkill?.name === skill.name ? null : skill);
  };

  return (
    <section id="skills" className="skills">
      <h2>Skills & Competencies</h2>

      <div className="skills-grid">
        <div className="skill-category">
          <h3>Technical Skills</h3>
          <div className="skill-list">
            {technicalSkills.map((skill, index) => (
              <div key={index}>
                <div 
                  className={`skill-item ${selectedSkill?.name === skill.name ? 'active' : ''}`}
                  onClick={() => handleSkillClick(skill)}
                >
                  <span>{skill.name}</span>
                </div>
                {selectedSkill?.name === skill.name && (
                  <div className="skill-description">
                    <p>{selectedSkill.description}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="skill-category">
          <h3>Project Management</h3>
          <div className="skill-list">
            {pmSkills.map((skill, index) => (
              <div key={index}>
                <div 
                  className={`skill-item ${selectedSkill?.name === skill.name ? 'active' : ''}`}
                  onClick={() => handleSkillClick(skill)}
                >
                  <span>{skill.name}</span>
                </div>
                {selectedSkill?.name === skill.name && (
                  <div className="skill-description">
                    <p>{selectedSkill.description}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>

        <div className="skill-category">
          <h3>Tools & Platforms</h3>
          <div className="skill-list">
            {tools.map((tool, index) => (
              <div key={index}>
                <div 
                  className={`skill-item ${selectedSkill?.name === tool.name ? 'active' : ''}`}
                  onClick={() => handleSkillClick(tool)}
                >
                  <span>{tool.name}</span>
                </div>
                {selectedSkill?.name === tool.name && (
                  <div className="skill-description">
                    <p>{selectedSkill.description}</p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

export default Skills;
